import java.util.*;

class Solution {
  public int minimumCost(String target, String[] words, int[] costs) {
    int total = 1;
    for (String w : words) total += w.length();
    int[] next = new int[total * 26],
        len = new int[total],
        link = new int[total],
        dict = new int[total];
    int[] cost = new int[total];
    final int INF = Integer.MAX_VALUE / 2;
    Arrays.fill(cost, INF);
    int nodes = 1;
    for (int i = 0; i < words.length; i++) {
      int cur = 0;
      for (int j = 0; j < words[i].length(); j++) {
        int c = words[i].charAt(j) - 'a';
        if (next[cur * 26 + c] == 0) {
          len[nodes] = len[cur] + 1;
          next[cur * 26 + c] = nodes++;
        }
        cur = next[cur * 26 + c];
      }
      cost[cur] = Math.min(cost[cur], costs[i]);
    }
    // BFS: fill goto transitions, suffix links and links to the nearest terminal suffix
    int[] queue = new int[nodes];
    int head = 0, tail = 0;
    for (int c = 0; c < 26; c++) if (next[c] != 0) queue[tail++] = next[c];
    while (head < tail) {
      int u = queue[head++];
      dict[u] = cost[link[u]] < INF ? link[u] : dict[link[u]];
      for (int c = 0; c < 26; c++) {
        int v = next[u * 26 + c];
        if (v == 0) {
          next[u * 26 + c] = next[link[u] * 26 + c];
        } else {
          link[v] = next[link[u] * 26 + c];
          queue[tail++] = v;
        }
      }
    }
    int n = target.length();
    int[] dp = new int[n + 1];
    Arrays.fill(dp, INF);
    dp[0] = 0;
    int state = 0;
    for (int i = 1; i <= n; i++) {
      state = next[state * 26 + target.charAt(i - 1) - 'a'];
      // distinct lengths along the chain, so at most sqrt(2 * total) iterations
      for (int v = cost[state] < INF ? state : dict[state]; v != 0; v = dict[v]) {
        int prev = dp[i - len[v]];
        if (prev < INF) dp[i] = Math.min(dp[i], prev + cost[v]);
      }
    }
    return dp[n] >= INF ? -1 : dp[n];
  }
}
